// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Phenomena".

Just a blob with holes.

*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, moves=[0,0];

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2925754/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	mouseMove()
	shader(theShader)
	theShader.setUniform("resolution", [width * scale, height * scale])
	theShader.setUniform("time", millis() / 1000.0)
	theShader.setUniform("move", moves)
	rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define hue(a) (.5+.5*sin(6.3*(a)+vec3(1,2,3)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// Forward declaration of the render function (function prototype)
vec3 render(vec2 uv);
// Since the function prototype is known here, main can be defined here, too.
// Why? Because we can! Phenomenal!
void main() { O=vec4(render((FC-.5*R)/MN),1); }
// White noise function of a scalar
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Interpolation between two random values
float curve(float t, float e) {
	t/=e;
	return mix(
		rnd(floor(t)),
		rnd(floor(t+1.)),
		pow(S(.0,1.,fract(t)),10.)
	);
}
// White noise function of a 2d vector
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Value noise funtction of a 2d vector
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Sinusoidal noise function of a 3d vector
float snoise(vec3 p) {
	float t = T*.5;
	for (int i; i++<3;) {
		p+=cos(p.zyx*3.+vec3(0,t,1.6))/3.;
		p+=sin(p.zyx+t+vec3(t,1.6,0))/2.;
		p+=sin(p.zyx+t*2.+vec3(0,1.6,t))/6.;
		p*=1.75;
	}
	p+=fract(sin(p+vec3(13,7,3))*5e5)*.03-.015; 
	return fract(noise(p.xy)*noise(p.yz));
}
// Compound sinusoidal noise function
vec2 noise(vec3 p) {
  return vec2(snoise(p), snoise(p*4.));
}
// Smooth minimum of two 3d vectors
vec3 smin(vec3 a, vec3 b, float k) {
	vec3 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// Smooth minimum of two scalars
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// Kaleidoscopic iterated function system
vec3 kifs(vec3 p) {
	for (float i=.0; i<3.; i++) {
		p.yz*=rot(T);
		p.xz*=rot(T-curve(T,.4));
		p=smin(p,-p,-1.);
		p-=vec3(.26,.02,.1);
	}
	return p;
}
// Distance function of the scene
float map(vec3 p) {
	vec3 q=p;
	q.yz*=rot(.39);
	return abs(smin(
		// the 'body' (outer and inner part)
		abs(length(kifs(p))-.525)-.2,
		// the ventilation system (most important part)
		-min(min(length(q.yz)-.0125,length(q.xy)-.0125),length(q.xz)-.0125),
		-.05
	))-.1; // outer 'skin' (no holes in the outer layer - that’s truly a phenomenon!)
}
// Normal vector of the surface at point p
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
// Ambient occlusion function
float occ(vec3 p, vec3 n, float d) {
	return map(p+n*d)/d;
}
// Camera rotation 
void cam(inout vec3 p) {
	p.yz*=rot(1.57-move.y*6.3/MN);
	p.xz*=rot(3.14-move.x*6.3/MN);
}
// Render function
vec3 render(vec2 uv) {
	// initialize output color vector 
	vec3 col=vec3(0),
	// the camera's position
	p=vec3(0,0,-2),
	// the frustum
	rd=N(vec3(uv,.2)),
	// the light's position
	lp=vec3(2,3,-8);
	// apply camera rotation
	cam(p); cam(rd);
	// initialize distance accumulation, glow accumulation, the side and the fallof
	float dd=.0, at=.0, side=1., e=1.;
	// march the scene
	for (int i; i++<300;) {
		// get the distance to the nearest surface at point p
		float d=map(p)*side;
		// check if a surface is hit (in very close vicinity of point p)
		if (abs(d)<1e-3) {
			// if a surface is hit, calculate its normal vector and the normalized light vector
			vec3 n=norm(p)*side, l=N(lp-p);
			// if inside the glass, invert the light vector, else no specular light inside
			if (dot(l,n)<.0) l=-l;
			// calculate diffuse light, ambient occlusion, fresnel and specular light
			float dif=clamp(dot(l,n),.0,1.), ao=occ(p,n,1.5)*occ(p,n,1.),
			fre=pow(clamp(1.+dot(rd,n),.0,1.),5.), spe=pow(clamp(dot(reflect(rd,n),l),.0,1.),32.);
			// apply color based on light
			col+=(.08*dif*ao+.2*fre)*e*vec3(6,2,4);
			// apply specular light
			col+=spe*e;
			// switch side for next render step
			side=-side;
			// calculate new ray direction (refraction)
			vec3 rdo=refract(rd,n,1.+side*.38);
			// if light grazes the surface (90°, dark), use reflection instead
			if (dot(rdo,rdo)==.0) rdo=reflect(rd,n);
			// apply new ray direction
			rd=rdo;
			// set distance to surface to a constant value (avoids artifacts)
			d=9e-3;
			// reduce falloff value
			e*=.5;
		}
		// check if ray did not hit anyhing and reached its maximum (sphere with radius 10 around scene)
		if (d>10.) {
			// get compound noise for a spherical space around the scene
			vec2 cn=noise(rd.xyx);
			// apply pattern based on multiple layers of noise
			col+=.3*(cn.x+cn.y+snoise(rd.xyx+snoise(rd.yxy))*hue(rd.y*5e1));
			// end marching loop
			break;
		}
		// advance the ray-marcher by the current distance to the scene
		p+=rd*d;
		// accumulate all distances
		dd+=d;
		// accumulate glow
		at+=.05*(.05/dd);
	}
	// amplify glow
	at*=2.;
	// apply glow
	col+=at*at;
	// increase contrast (darkens the scene)
	col=tanh(col*col*col);
	// quick gamma correction (adds back some light)
	col=sqrt(col);
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float vig=c.x*c.y*25.;
	vig=sqrt(vig);
	col*=vig;
	return col;
}

